/**
 * A WebGL implementation of the Buffer.
 *
 * @ignore
 */
export class WebglBuffer {
    bufferId: any;
    /** @type {Uint8Array|null} */
    uploadView: Uint8Array | null;
    destroy(device: any): void;
    get initialized(): boolean;
    loseContext(): void;
    unlock(device: any, usage: any, target: any, storage: any, byteOffset?: number, byteLength?: number): void;
}
